<?php declare(strict_types=1); $accesses = is_array($accesses ?? null) ? $accesses : []; ?>
<div class="mb-4"><h1 class="h3">Accesos a contenido</h1><p class="text-muted">Últimos intentos de entrega protegida.</p></div><div class="alert alert-info">La protección controla el acceso desde el servidor, caduca los enlaces y deja trazabilidad. No puede impedir una captura o grabación realizada fuera de la plataforma.</div><div class="admin-card card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Fecha</th><th>Curso / lección</th><th>Acción</th><th>Resultado</th><th>IP</th></tr></thead><tbody><?php foreach ($accesses as $access): ?><tr><td><?= e((string) $access['created_at']) ?></td><td><?= e((string) ($access['course_title'] ?? '')) ?><br><small><?= e((string) ($access['lesson_title'] ?? '')) ?></small></td><td><?= e((string) $access['action']) ?></td><td><?= (int) $access['delivered'] === 1 ? 'Permitido' : 'Denegado: ' . e((string) ($access['reason'] ?? '')) ?></td><td><?= e((string) ($access['ip'] ?? '')) ?></td></tr><?php endforeach; ?><?php if ($accesses === []): ?><tr><td colspan="5" class="text-center py-4">Todavía no hay accesos registrados.</td></tr><?php endif; ?></tbody></table></div></div>